import{canManageMaintenanceVendors}from'@/lib/permissions';
import{NextResponse}from'next/server';import{getSession,originAllowed}from'@/lib/session';import{vendorSchema}from'@/lib/validation';import{createVendor}from'@/lib/operations';
export async function POST(req:Request){const session=await getSession();if(!session)return NextResponse.json({error:'يرجى تسجيل الدخول أولاً.'},{status:401});if(!canManageMaintenanceVendors(session.role))return NextResponse.json({error:'ليست لديك صلاحية تنفيذ هذه العملية.'},{status:403});if(!session)return NextResponse.json({error:'يرجى تسجيل الدخول أولاً.'},{status:401});if(!originAllowed(req))return NextResponse.json({error:'مصدر الطلب غير صالح.'},{status:403});let body:unknown;try{body=await req.json()}catch{return NextResponse.json({error:'بيانات الطلب غير صالحة.'},{status:400})}const p=vendorSchema.safeParse(body);if(!p.success)return NextResponse.json({error:p.error.issues[0]?.message??'تحقق من بيانات المورد.'},{status:400});try{return NextResponse.json({ok:true,id:await createVendor(p.data,session.userId)})}catch{return NextResponse.json({error:'تعذر حفظ المورد.'},{status:400})}}
